def deduplicate_before_constraints(apps, schema_editor):
    """تطبيع القيم الفارغة وإزالة أي تكرار قبل إضافة قيود الفرادة (UniqueConstraint)."""
    QCRecord = apps.get_model('api', 'QCRecord')
    HRAttendanceRecord = apps.get_model('api', 'HRAttendanceRecord')

    # 1) Normalize NULL color_name / size to empty strings before non-null AlterField & constraint.
    QCRecord.objects.filter(color_name__isnull=True).update(color_name='')
    QCRecord.objects.filter(size__isnull=True).update(size='')

    # 2) Deduplicate QCRecord by (model_id, stage, part_type, color_name, size), keeping latest id.
    seen_qc = {}
    duplicate_qc_ids = []
    for row in QCRecord.objects.order_by('-id').values('id', 'model_id', 'stage', 'part_type', 'color_name', 'size'):
        key = (
            row['model_id'],
            row['stage'] or '',
            row['part_type'] or 'shirt',
            row['color_name'] or '',
            row['size'] or '',
        )
        if key in seen_qc:
            duplicate_qc_ids.append(row['id'])
        else:
            seen_qc[key] = row['id']
    if duplicate_qc_ids:
        QCRecord.objects.filter(id__in=duplicate_qc_ids).delete()

    # 3) Deduplicate HRAttendanceRecord by (employee_id, date), keeping latest id.
    seen_att = {}
    duplicate_att_ids = []
    for row in HRAttendanceRecord.objects.order_by('-id').values('id', 'employee_id', 'date'):
        key = (row['employee_id'], row['date'])
        if key in seen_att:
            duplicate_att_ids.append(row['id'])
        else:
            seen_att[key] = row['id']
    if duplicate_att_ids:
        HRAttendanceRecord.objects.filter(id__in=duplicate_att_ids).delete()


